import {transitions} from './workflow.mjs';
export function workflowView(s,projects,safe,{selectedWork,historyProject,historyActor}){
  const selected=s.workItems.find(w=>w.id===selectedWork)||s.workItems[0];
  const timeline=selected?s.workflowEvents.filter(e=>e.entityType==='work'&&e.entityId===selected.id):[];
  const filtered=s.workflowEvents.filter(e=>(historyProject==='all'||e.project===historyProject)&&(!historyActor||e.actor.toLowerCase().includes(historyActor.toLowerCase())));
  const snapshots=e=>{const keys=[...new Set([...Object.keys(e.before||{}),...Object.keys(e.after||{})])].filter(k=>JSON.stringify(e.before?.[k])!==JSON.stringify(e.after?.[k]));return `<dl class="step-diff">${keys.map(k=>`<div><dt>${safe(k)}</dt><dd>${safe(e.before?.[k]??'—')} <span>→</span> ${safe(e.after?.[k]??'—')}</dd></div>`).join('')}</dl>`};
  const event=e=>`<li class="workflow-event"><div class="risk-line"><b>${safe(e.action)}</b><small>${safe(new Date(e.time).toLocaleString('en-US',{timeZone:'UTC'}))} UTC</small></div><p class="event-actor">${safe(e.actor)} · ${safe(e.entityId)} · ${e.source==='seed'?'Simulated starting record':'Recorded operator action'}</p><p>${safe(e.note)}</p>${snapshots(e)}</li>`;
  return `<section class="card operator-card"><div class="panel-body"><label for="operator-name">Current operator</label><div class="actions"><input id="operator-name" maxlength="80" value="${safe(s.operatorName)}"><button class="btn" id="save-operator">Set operator name</button></div><p class="definition">Self-declared demo identity, saved on this device. Every business action records this name; changing it does not rename earlier history. Verified accounts require a shared backend.</p></div></section>
  <div class="workflow-grid"><section class="card"><div class="card-head"><div><h2>Work items</h2><p>Each deliverable keeps its own sequence of steps.</p></div><span class="badge gray">${s.workItems.length} records</span></div><div class="work-list">${s.workItems.map(w=>`<button class="work-item ${selected?.id===w.id?'selected':''}" data-work="${w.id}"><span><b>${safe(w.title)}</b><small>${w.id} · ${safe(projects.find(p=>p.id===w.project).name)}</small><small>${safe(s.workers.find(a=>a.id===w.owner).name)}</small></span><span class="badge ${w.status==='Accepted'?'green':w.status==='Rejected'?'red':'gray'}">${w.status}</span></button>`).join('')}</div><details class="new-work"><summary>Create a work item</summary><form id="new-work-form"><label for="work-title">Deliverable / product</label><input id="work-title" name="title" required maxlength="160" placeholder="Example: recording batch 025"><label for="work-project">Project</label><select id="work-project" name="project">${projects.map(p=>`<option value="${p.id}">${safe(p.name)}</option>`).join('')}</select><label for="work-owner">Assigned worker</label><select id="work-owner" name="owner">${s.workers.map(w=>`<option value="${w.id}">${safe(w.name)} · ${w.id} · ${w.qualified.join('/')}</option>`).join('')}</select><label for="work-assignment-note">Assignment instructions</label><textarea id="work-assignment-note" name="note" required maxlength="1000"></textarea><button class="btn primary" type="submit">Create & record assignment</button><p class="definition">Qualification is checked before creating the work item. Work items illustrate lifecycle tracking and do not change aggregate historical delivery metrics.</p></form></details></section>
  <section class="card"><div class="card-head"><div><h2>${selected?safe(selected.title):'Work history'}</h2><p>Assignment → execution → submission → review → outcome</p></div></div><div class="panel-body">${selected?`<div class="workflow-path">${['Assigned','In progress','Submitted','Review outcome'].map((name,i)=>`<span class="${selected.status===name||(i===3&&['Accepted','Rejected','Rework'].includes(selected.status))?'current':''}">${name}</span>`).join('')}</div><p><b>Current stage:</b> ${selected.status} · <b>Owner:</b> ${safe(s.workers.find(w=>w.id===selected.owner).name)}</p>${selected.output?`<p class="output-reference"><b>Output reference:</b> ${safe(selected.output)}</p>`:''}${transitions[selected.status].length?`<form id="advance-work-form"><label for="work-next">Next workflow step</label><select id="work-next" name="next">${transitions[selected.status].map(t=>`<option>${t}</option>`).join('')}</select><label for="work-note">Work performed / review decision</label><textarea id="work-note" name="note" required maxlength="1000" placeholder="Describe what was done, checked or returned for rework."></textarea><label for="work-output">Output reference</label><input id="work-output" name="output" maxlength="500" value="${safe(selected.output)}" placeholder="Batch ID, document reference or deliverable name"><p class="definition">Required at submission. References are text; files are not uploaded.</p><button class="btn primary" type="submit">Record step & update work</button></form>`:'<div class="callout">This work item has reached its final outcome. Its previous steps remain available below.</div>'}<h3 class="history-title">Complete workflow history · ${timeline.length} steps</h3><ol class="workflow-timeline">${timeline.map(event).join('')}</ol>`:'<p>No work items yet. Create one to begin tracking.</p>'}</div></section></div>
  <section class="card history-register"><div class="card-head"><div><h2>Operations history across records</h2><p>Work, repair appointments, technician issues and client impacts, staffing, QA, incidents and scenarios.</p></div><button class="btn" id="download-workflow">Export workflow history · CSV</button></div><div class="panel-body"><div class="filters"><label for="history-project">Project</label><select id="history-project"><option value="all">All projects</option>${projects.map(p=>`<option value="${p.id}" ${historyProject===p.id?'selected':''}>${safe(p.name)}</option>`).join('')}</select><label for="history-actor">Operator</label><input id="history-actor" value="${safe(historyActor)}" placeholder="Filter by recorded operator"></div><p class="definition">${filtered.length} matching events. Imported/local history is editable demo data; it is not a tamper-proof or independently verified audit. Activity from before this tracking upgrade is not reconstructed.</p><ol class="workflow-timeline">${filtered.slice().reverse().map(event).join('')||'<li>No recorded actions match these filters.</li>'}</ol></div></section>`;
}
